-- SemaBridge Native App setup script (TEMPLATE: validate before listing).
-- Runs in the consumer account on install and upgrade.

CREATE APPLICATION ROLE IF NOT EXISTS app_user;
CREATE OR ALTER VERSIONED SCHEMA core;
GRANT USAGE ON SCHEMA core TO APPLICATION ROLE app_user;

-- Session-signing and credential-encryption keys are generated by the
-- container on first start and kept on its persistent volume.

-- Reference callbacks for the optional external access integration.
CREATE OR REPLACE PROCEDURE core.register_reference(ref_name STRING, operation STRING, ref_or_alias STRING)
RETURNS STRING
LANGUAGE SQL
AS $$
BEGIN
  CASE (operation)
    WHEN 'ADD' THEN SELECT SYSTEM$SET_REFERENCE(:ref_name, :ref_or_alias);
    WHEN 'REMOVE' THEN SELECT SYSTEM$REMOVE_REFERENCE(:ref_name, :ref_or_alias);
    WHEN 'CLEAR' THEN SELECT SYSTEM$REMOVE_ALL_REFERENCES(:ref_name);
    ELSE RETURN 'unknown operation: ' || operation;
  END CASE;
  RETURN NULL;
END;
$$;
GRANT USAGE ON PROCEDURE core.register_reference(STRING, STRING, STRING) TO APPLICATION ROLE app_user;

CREATE OR REPLACE PROCEDURE core.get_configuration(ref_name STRING)
RETURNS STRING
LANGUAGE SQL
AS $$
BEGIN
  RETURN '{"type": "CONFIGURATION", "payload": {"host_ports": ["api.powerbi.com", "login.microsoftonline.com", "api.fabric.microsoft.com"], "allowed_secrets": "NONE"}}';
END;
$$;
GRANT USAGE ON PROCEDURE core.get_configuration(STRING) TO APPLICATION ROLE app_user;

-- Start (or restart) the service. The consumer calls this after granting
-- the CREATE COMPUTE POOL and BIND SERVICE ENDPOINT privileges.
CREATE OR REPLACE PROCEDURE core.start_app()
RETURNS STRING
LANGUAGE SQL
AS $$
BEGIN
  CREATE COMPUTE POOL IF NOT EXISTS semabridge_pool
    MIN_NODES = 1 MAX_NODES = 1 INSTANCE_FAMILY = CPU_X64_S AUTO_RESUME = TRUE;
  CREATE SERVICE IF NOT EXISTS core.semabridge
    IN COMPUTE POOL semabridge_pool
    FROM SPECIFICATION_FILE = 'service.yaml';
  GRANT USAGE ON SERVICE core.semabridge TO APPLICATION ROLE app_user;
  GRANT SERVICE ROLE core.semabridge!ALL_ENDPOINTS_USAGE TO APPLICATION ROLE app_user;
  RETURN 'SemaBridge service started';
END;
$$;
GRANT USAGE ON PROCEDURE core.start_app() TO APPLICATION ROLE app_user;
